from datetime import datetime


def interval_layout(day, intervals, window_start, window_end):
    """Clip intervals to one day window and give simultaneous events separate equal-width lanes.

    Return dictionaries with original indices, minute offsets, durations, lane and lane count.
    Touching events can share a lane. Off-window intervals are omitted without changing inputs.
    """
    start = datetime.combine(day, window_start)
    end = datetime.combine(day, window_end)
    if end <= start:
        raise ValueError('The timetable window must end after its start.')
    visible = []
    for index, (beginning, finish) in enumerate(intervals):
        if finish <= beginning:
            raise ValueError('Calendar intervals must have a positive duration.')
        if beginning < end and finish > start:
            visible.append((max(beginning, start), min(finish, end), index))
    visible.sort()
    result, group, group_end = [], [], start
    for beginning, finish, index in visible:
        if group and beginning >= group_end:
            result.extend(_lane_group(group, start))
            group = []
        group.append((beginning, finish, index))
        group_end = max(group_end, finish)
    return result + _lane_group(group, start)


def _lane_group(group, window_start):
    """Use the first available lane and share one width across a connected overlap group."""
    ends, result = [], []
    # Course: L03 – a bounded search reuses lanes whose previous interval has ended.
    for beginning, finish, index in group:
        lane = next((i for i, ending in enumerate(ends) if ending <= beginning), len(ends))
        if lane == len(ends):
            ends.append(finish)
        else:
            ends[lane] = finish
        result.append({'index': index, 'offset': (beginning - window_start).total_seconds() / 60,
                       'minutes': (finish - beginning).total_seconds() / 60, 'lane': lane})
    for item in result:
        item['lanes'] = len(ends)
    return result
